def topo(n, edges):
    """DFS 后序逆序 + 三色标记判环。有环则返回 []。
    color: 0 白(未访问) / 1 灰(在递归栈上) / 2 黑(已完成)。"""
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
    color = [0] * n
    order = []
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        color[u] = 1                       # 进栈,染灰
        for w in g[u]:
            if color[w] == 1:              # 指回栈内 → 回边 → 有环
                has_cycle = True
                return
            if color[w] == 0:
                dfs(w)
                if has_cycle:
                    return
        color[u] = 2                       # 子树处理完,染黑
        order.append(u)                    # 收集后序

    for i in range(n):
        if color[i] == 0:
            dfs(i)
            if has_cycle:
                return []
    order.reverse()                        # 后序反转即拓扑序
    return order

