import random
from itertools import permutations
random.seed(20240614)


def is_valid_topo(n, edges, order):
    if order is None:
        return False
    if sorted(order) != list(range(n)):
        return False
    pos = {x: i for i, x in enumerate(order)}
    return all(pos[u] < pos[v] for u, v in edges)


def brute_lex(n, edges):
    # permutations 按字典序产出,首个合法拓扑序即字典序最小
    for p in permutations(range(n)):
        if is_valid_topo(n, edges, list(p)):
            return list(p)
    return None


# 边界与特例
assert topo(0, []) == []
assert topo(1, []) == [0]
assert topo(1, [(0, 0)]) == []
assert topo(2, [(0, 1), (1, 0)]) == []
assert topo(2, [(1, 0)]) == [1, 0]                  # 约束优先于字典序
assert topo(3, [(2, 0)]) == [1, 2, 0]               # 自由点 1 先于受约束的 2

# 随机小 DAG:与暴力枚举的字典序最小拓扑序对拍
for _ in range(150):
    n = random.randint(0, 6)
    perm = list(range(n))
    random.shuffle(perm)
    rank = {node: i for i, node in enumerate(perm)}
    edges = []
    for u in range(n):
        for v in range(n):
            if rank[u] < rank[v] and random.random() < 0.3:
                edges.append((u, v))
    order = topo(n, edges)
    assert is_valid_topo(n, edges, order), (n, edges, order)
    assert order == brute_lex(n, edges), (n, edges, order)

# 随机带环图必返回 []
for _ in range(120):
    n = random.randint(2, 7)
    edges = []
    for u in range(n):
        for v in range(n):
            if u != v and random.random() < 0.18:
                edges.append((u, v))
    k = random.randint(2, n)
    cyc = random.sample(range(n), k)
    for i in range(k):
        edges.append((cyc[i], cyc[(i + 1) % k]))
    assert topo(n, edges) == [], (n, edges)
